window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-shift-hours.html"]="<!-- Settings: Organisasi — Jadwal Kerja (Shift Hours) -->\n<style>\n.st-shift-form label{display:block;font-size:13px;font-weight:500;margin-bottom:12px}\n.st-shift-form label input,.st-shift-form label select{display:block;width:100%;padding:8px 10px;border:1px solid var(--border);border-radius:8px;margin-top:4px;font-size:13px;background:var(--bg)}\n.st-shift-form label input:focus,.st-shift-form label select:focus{outline:2px solid var(--accent);outline-offset:-1px}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\" id=\"stNav\"></aside>\n  <div class=\"settings-body\">\n    <div style=\"display:flex;align-items:center;justify-content:space-between;margin-bottom:16px\">\n      <div><h2 style=\"margin-bottom:4px\">Jadwal Kerja</h2><p style=\"font-size:13px;color:var(--muted)\">Atur shift kerja agen.</p></div>\n      <button class=\"btn primary\" onclick=\"openShiftModal()\">+ Tambah Shift</button>\n    </div>\n\n    <div class=\"card\" style=\"padding:0;overflow:hidden\">\n      <table class=\"data-table\">\n        <thead><tr><th>Nama Shift</th><th>Jam Mulai</th><th>Jam Selesai</th><th>Hari</th><th>Aksi</th></tr></thead>\n        <tbody id=\"shiftBody\"></tbody>\n      </table>\n    </div>\n\n    <!-- Add/Edit shift modal -->\n    <div class=\"modal-overlay\" id=\"modalShift\">\n      <div class=\"modal\">\n        <h3 id=\"shiftModalTitle\">Tambah Shift</h3>\n        <div class=\"st-shift-form\">\n          <label>Nama Shift<input type=\"text\" id=\"sfName\"></label>\n          <label>Jam Mulai<input type=\"time\" id=\"sfStart\"></label>\n          <label>Jam Selesai<input type=\"time\" id=\"sfEnd\"></label>\n          <label>Hari<select id=\"sfDays\"><option>Senin-Jumat</option><option>Sabtu-Minggu</option><option>Senin-Minggu</option><option>Senin-Kamis</option><option>Jumat-Minggu</option></select></label>\n        </div>\n        <div class=\"modal-actions\"><button class=\"btn\" onclick=\"closeShiftModal()\">Batal</button><button class=\"btn primary\" onclick=\"saveShift()\">Simpan</button></div>\n      </div>\n    </div>\n\n    <!-- Delete confirm -->\n    <div class=\"modal-overlay\" id=\"modalShiftDel\">\n      <div class=\"modal\">\n        <h3>Hapus Shift</h3>\n        <p style=\"font-size:13px;color:var(--muted);margin-bottom:10px\" id=\"shiftDelMsg\"></p>\n        <div class=\"modal-actions\"><button class=\"btn\" onclick=\"document.getElementById('modalShiftDel').classList.remove('open')\">Batal</button><button class=\"btn danger\" onclick=\"confirmShiftDel()\">Hapus</button></div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  document.getElementById('stNav').innerHTML=renderSettingsNav('organization-shift-hours');\n\n  let editingShiftId=null;\n  let delShiftId=null;\n\n  function render(){\n    const tbody=document.getElementById('shiftBody');\n    if(!DB.settings.shiftHours.length){tbody.innerHTML='<tr><td colspan=\"5\" style=\"text-align:center;padding:32px;color:var(--muted)\">Belum ada shift.</td></tr>';return}\n    tbody.innerHTML=DB.settings.shiftHours.map(s=>`<tr>\n      <td><strong>${s.name}</strong></td>\n      <td>${s.start}</td>\n      <td>${s.end}</td>\n      <td>${s.days}</td>\n      <td>\n        <button class=\"btn\" style=\"font-size:11px;padding:3px 10px\" onclick=\"openShiftModal('${s.id}')\">✏</button>\n        <button class=\"btn danger\" style=\"font-size:11px;padding:3px 10px\" onclick=\"openShiftDel('${s.id}')\">🗑</button>\n      </td>\n    </tr>`).join('');\n  }\n  render();\n\n  window.openShiftModal=function(id){\n    editingShiftId=id||null;\n    document.getElementById('shiftModalTitle').textContent=id?'Edit Shift':'Tambah Shift';\n    if(id){\n      const s=DB.settings.shiftHours.find(x=>x.id===id);\n      document.getElementById('sfName').value=s.name;\n      document.getElementById('sfStart').value=s.start;\n      document.getElementById('sfEnd').value=s.end;\n      document.getElementById('sfDays').value=s.days;\n    }else{\n      document.getElementById('sfName').value='';\n      document.getElementById('sfStart').value='08:00';\n      document.getElementById('sfEnd').value='16:00';\n      document.getElementById('sfDays').value='Senin-Jumat';\n    }\n    document.getElementById('modalShift').classList.add('open');\n  };\n\n  window.closeShiftModal=function(){document.getElementById('modalShift').classList.remove('open')};\n\n  window.saveShift=function(){\n    const name=document.getElementById('sfName').value.trim();\n    if(!name){showToast('Nama shift wajib diisi');return}\n    const data={name,start:document.getElementById('sfStart').value,end:document.getElementById('sfEnd').value,days:document.getElementById('sfDays').value};\n    if(editingShiftId){\n      const s=DB.settings.shiftHours.find(x=>x.id===editingShiftId);\n      Object.assign(s,data);\n    }else{\n      DB.settings.shiftHours.push({id:genId('sh'),...data});\n    }\n    saveStore();render();closeShiftModal();\n    showToast(editingShiftId?'Shift diperbarui':'Shift ditambahkan');\n  };\n\n  window.openShiftDel=function(id){\n    delShiftId=id;\n    const s=DB.settings.shiftHours.find(x=>x.id===id);\n    document.getElementById('shiftDelMsg').textContent=`Yakin ingin menghapus shift \"${s.name}\"?`;\n    document.getElementById('modalShiftDel').classList.add('open');\n  };\n\n  window.confirmShiftDel=function(){\n    DB.settings.shiftHours=DB.settings.shiftHours.filter(x=>x.id!==delShiftId);\n    saveStore();render();\n    document.getElementById('modalShiftDel').classList.remove('open');\n    showToast('Shift dihapus');\n  };\n})();\n</script>\n";
